<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{WorkflowRepository,SettingsRepository,AcademicRepository,SupportRepository,StudentRepository};use App\Support\Flash;
final class ExamsController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function w():WorkflowRepository{return new WorkflowRepository($this->app->database());}private function data():array{$i=$this->i();return['exams'=>$this->w()->exams($i),'classes'=>(new AcademicRepository($this->app->database()))->classes($i),'subjects'=>(new SupportRepository($this->app->database()))->subjects($i)];}
/**
 * Teachers (the teacher role without the admin wildcard) may only enter marks, and only for the
 * classes and subjects they are assigned to. Creating, configuring, publishing and results stay
 * with administrators and principals. Returns the teacher's employee id, or null for full access.
 */
private function teacherScope():?int{if(can('*')||!hasRole('teacher'))return null;$e=(int)$this->app->database()->query('SELECT ea.employee_id FROM employee_accounts ea JOIN employees e ON e.id=ea.employee_id WHERE ea.user_id=:u AND e.institute_id=:i',['u'=>(int)user()['id'],'i'=>$this->i()])->fetchColumn();return$e?:-1;}
private function teacherDenied():?Response{return$this->teacherScope()!==null?Response::html(\App\Core\View::render('errors/403',['pageTitle'=>'Access Denied'],'layouts/error'),403):null;}
private function teacherSetups():array{$all=$this->w()->examSetups($this->i());$e=$this->teacherScope();if($e===null)return$all;if($e<0)return[];$erp=new \App\Repositories\PakistanErpRepository($this->app->database());return array_values(array_filter($all,fn($s)=>$erp->teacherCan($e,$this->i(),(int)$s['class_id'],(int)$s['subject_id'])));}
public function create(Request$r):Response{return Response::redirect(url('/admin/exams'));}public function store(Request$r):Response{if($x=$this->teacherDenied())return$x;try{$this->w()->createExam($this->i(),(string)$r->input('examname'),(string)$r->input('startdate'),(string)$r->input('enddate'),(int)user()['id']);}catch(\Throwable$e){return Response::html(e($e->getMessage()),422);}Flash::add('success','Exam created.');return Response::redirect(url('/admin/exams'));}public function delete(Request$r):Response{if($x=$this->teacherDenied())return$x;if(!$this->w()->deleteExam($this->i(),(int)$r->route('id')))return Response::html('Exam not found',404);Flash::add('success','Exam deleted.');return Response::redirect(url('/admin/exams'));}
public function setup(Request$r):Response{if($x=$this->setupDenied())return$x;[$classes,$subjects]=$this->setupChoices();return$this->renderPage('exam-setup',['exams'=>$this->w()->exams($this->i()),'classes'=>$classes,'subjects'=>$subjects,'setups'=>$this->teacherScope()===null?$this->w()->examSetups($this->i()):$this->teacherSetups(),'isTeacher'=>$this->teacherScope()!==null]);}
/** Teachers may use Exam Setup only when the admin allows teachers to add papers. */
private function setupDenied():?Response{if($this->teacherScope()===null)return null;if($this->teacherScope()<0||!(new \App\Repositories\ExamCenterRepository($this->app->database()))->settings($this->i())['teachers_add_papers'])return$this->teacherDenied();return null;}
/** Classes and class subjects offered on the form (a teacher only sees their own). */
private function setupChoices():array{$classes=(new AcademicRepository($this->app->database()))->classes($this->i());$subjects=(new SupportRepository($this->app->database()))->subjects($this->i());$e=$this->teacherScope();if($e!==null){$erp=new \App\Repositories\PakistanErpRepository($this->app->database());$subjects=array_values(array_filter($subjects,fn($s)=>$erp->teacherCan($e,$this->i(),(int)$s['class_id'],(int)$s['id'])));$ids=array_unique(array_map('intval',array_column($subjects,'class_id')));$classes=array_values(array_filter($classes,fn($c)=>in_array((int)$c['id'],$ids,true)));}return[$classes,$subjects];}
public function deleteSetup(Request$r):Response{if($x=$this->teacherDenied())return$x;try{if(!$this->w()->deleteExamSetup($this->i(),(int)$r->route('id')))return Response::html('Exam setup not found',404);\App\Support\Flash::add('success','Subject removed from the exam.');}catch(\DomainException$e){\App\Support\Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/exams/setup'));}public function saveSetup(Request$r):Response{if($x=$this->setupDenied())return$x;
// One or many classes and one or many subjects: a paper is made for every class + subject pair
// where that class actually studies the subject. Existing papers are left as they are.
$classes=array_values(array_unique(array_filter(array_map('intval',(array)$r->input('classes',[$r->input('class')])))));$subjects=array_values(array_unique(array_filter(array_map('intval',(array)$r->input('subjects',[$r->input('subject')])))));$total=(float)$r->input('total_marks');$exam=(int)$r->input('exam');
if(!$classes||!$subjects){Flash::add('error','Choose at least one class and one subject.');return Response::redirect(url('/admin/exams/setup'));}
$center=new \App\Repositories\ExamCenterRepository($this->app->database());$e=$this->teacherScope();$erp=$e!==null?new \App\Repositories\PakistanErpRepository($this->app->database()):null;$added=0;$existing=[];$skipped=[];
try{foreach($classes as$c){$taught=array_map('intval',array_column($center->classSubjects($c),'id'));$mine=array_values(array_filter($subjects,fn($s)=>in_array($s,$taught,true)&&($erp===null||$erp->teacherCan($e,$this->i(),$c,$s))));$skipped=array_merge($skipped,array_map(fn($s)=>[$c,$s],array_diff($subjects,$mine)));if(!$mine)continue;[$n,$have]=$center->addPapers($this->i(),$exam,$c,$mine,$total,(int)user()['id']);$added+=$n;foreach($have as$h)$existing[]=$h;}}catch(\DomainException$ex){Flash::add('error',$ex->getMessage());return Response::redirect(url('/admin/exams/setup'));}
Flash::add($added?'success':'error',$added?$added.' paper(s) added.':'No new papers were added.');if($existing)Flash::add('error','Already set up, left unchanged: '.implode(', ',array_unique($existing)).'.');if($skipped)Flash::add('error',count($skipped).' class + subject combination(s) skipped because that class does not study the subject'.($erp?' or you are not assigned to it':'').'.');return Response::redirect(url('/admin/exams/setup'));}
public function marks(Request$r):Response{$setup=(int)$r->query('setup',0);if($setup)return Response::redirect(url('/admin/exams/papers/'.$setup));$setups=$this->teacherSetups();if($setup&&!in_array($setup,array_map('intval',array_column($setups,'id')),true))$setup=0;return$this->renderPage('exam-marks',$this->data()+['setups'=>$setups,'selectedSetup'=>$setup,'students'=>$setup?$this->w()->examMarkSheet($this->i(),$setup):[]]);}public function saveMarks(Request$r):Response{if($this->teacherScope()!==null&&!in_array((int)$r->input('exam_subject_id'),array_map('intval',array_column($this->teacherSetups(),'id')),true))return Response::html('You are not assigned to that class and subject.',403);$paper=(new \App\Repositories\ExamCenterRepository($this->app->database()))->paper($this->i(),(int)$r->input('exam_subject_id'));if($paper&&($paper['exam_status']==='locked'||($this->teacherScope()!==null&&($paper['marks_status']==='submitted'||$paper['visible']))))return Response::html('These marks are locked, sent for review or published and can no longer be changed here.',422);try{$this->w()->saveExamMarks($this->i(),(int)$r->input('exam_subject_id'),(array)$r->input('marks',[]),(int)user()['id'],(array)$r->input('absent',[]));}catch(\DomainException$e){return Response::html(e($e->getMessage()),422);}\App\Support\Flash::add('success','Marks saved. Choose another exam / class / subject to continue, or reopen this one to check it.');return Response::redirect(url('/admin/exams/marks'));}
public function results(Request$r):Response{if($x=$this->teacherDenied())return$x;$exam=(int)$r->query('exam',0);$class=(int)$r->query('class',0);$student=(int)$r->query('student',0);return$this->renderPage('exam-results',$this->data()+['students'=>(new StudentRepository($this->app->database()))->paginate($this->i(),'',null),'selectedExam'=>$exam,'selectedClass'=>$class,'selectedStudent'=>$student,'result'=>$student&&$exam?$this->w()->studentResult($this->i(),$exam,$student):null,'rows'=>$class&&$exam?$this->w()->classResults($this->i(),$exam,$class):[]]);}
public function status(Request$r):Response{if($x=$this->teacherDenied())return$x;try{if(!$this->w()->setExamStatus($this->i(),(int)$r->route('id'),(string)$r->input('status')))return Response::html('Exam not found',404);Flash::add('success','Exam workflow status updated.');if((string)$r->input('status')==='published'){$queued=(new \App\Services\Sms\SmsAutomation($this->app->database()))->resultPublished($this->i(),(int)$r->route('id'));if($queued)Flash::add('success',$queued.' result SMS queued for the SMS gateway.');}}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/exams'));}
}
